// Cross-implementor cases for the AP2 PQC v1 construction, generated by pqam's independent
// implementation (ap2pqc-v1.mjs), for chopmob-cloud/ap2-pq-conformance's verifiers to run.
//   node interop/ap2-pq-conformance/build-cases.mjs  -> pqam-cross-v1.json (byte-reproducible)
//
// Group A (ES256 + Ed25519): every check is runnable by verify_v1.py today.
// Group B (ES256 + ML-DSA-65): the PQ hybrid. A verifier that checks ML-DSA-65 gives `expect`;
// verify_v1.py as published fails closed on every B case ("listed but not verifiable"), which is the
// correct behaviour and is recorded as `expect_verify_v1_without_mldsa65`.
import { readFileSync, writeFileSync } from "node:fs";
import { buildV1, keyFromSeed, verifyV1 } from "./ap2pqc-v1.mjs";

const UP = JSON.parse(readFileSync(new URL("upstream/ap2-pqc-v1-algovoi-side.json", import.meta.url), "utf8"));
const mandate_body = UP.mandate_body; // the same 501-byte JCS PaymentMandate both sides use
const SEEDS = { ES256: "pqam-cross/ES256/v1", Ed25519: "pqam-cross/Ed25519/v1", "ML-DSA-65": "pqam-cross/ML-DSA-65/v1" };
const K = Object.fromEntries(Object.entries(SEEDS).map(([a, s]) => [a, keyFromSeed(a, s)]));
const clone = (o) => structuredClone(o);

function group(id, algs) {
  const keys = algs.map((a) => K[a]);
  const [c, other] = algs; // c = classical ES256, other = Ed25519 or ML-DSA-65
  const valid = buildV1({ mandate_body, keys });
  const cases = [];
  const add = (name, description, artefact, expect) => cases.push({ id: `${id}.${name}`, description, expect, artefact });
  add("valid", `${algs.join(" + ")}, both signatures over the v1 signed input`, valid, { ok: true });
  const s1 = clone(valid); delete s1.signatures[c];
  add(`strip_${c}`, `the ${c} signature removed`, s1, { ok: false, error_contains: `missing signature for required signer: ${c}` });
  const s2 = clone(valid); delete s2.signatures[other];
  add(`strip_${other}`, `the ${other} signature removed${other === "ML-DSA-65" ? " (the post-quantum half: the Q-Day downgrade)" : ""}`, s2, { ok: false, error_contains: `missing signature for required signer: ${other}` });
  const s3 = clone(s2); s3.signer_set.signers = s3.signer_set.signers.filter((x) => x.algorithm !== other); delete s3.expected_signed_input_sha256;
  add(`strip_${other}_and_rewrite_descriptor`, `the ${other} signature removed AND the signer_set rewritten to list ${c} alone: the remaining signature was made over the two-signer descriptor`, s3, { ok: false, error_contains: `${c} verification failed` });
  const r = clone(valid); r.object_type = "Receipt"; delete r.expected_signed_input_sha256;
  add("relabel_object_type", "object_type relabelled PaymentMandate -> Receipt, signatures kept", r, { ok: false, error_contains: `${c} verification failed` });
  const k = clone(valid); k.signer_set.signers[0].key_id = "00".repeat(32); delete k.expected_signed_input_sha256;
  add("key_id_mismatch", `the ${c} key_id in the descriptor replaced`, k, { ok: false, error_contains: `key_id mismatch for ${c}` });
  const x = buildV1({ mandate_body, keys: [K[c]] });
  const xi = clone(x); xi.signatures[other] = buildV1({ mandate_body, keys }).signatures[other];
  add("unlisted_extra_signer", `signer_set lists ${c} alone; a ${other} signature is added`, xi, { ok: false, error_contains: `signature present for unlisted signer: ${other}` });
  const u = clone(valid); u.signer_set.signers.push({ algorithm: "SLH-DSA-SHAKE-256f", key_id: "11".repeat(32) }); delete u.expected_signed_input_sha256;
  add("unknown_algorithm_in_descriptor", "an algorithm no verifier knows added to the signer_set", u, { ok: false, error_contains: "signer_set lists no signers, or an unknown algorithm" });
  const b = clone(valid); b.mandate_body.amount.minor_units = 99500; delete b.expected_signed_input_sha256;
  add("body_edited", "amount.minor_units 4995 -> 99500 after signing", b, { ok: false, error_contains: `${c} verification failed` });
  return cases;
}

const A = group("A", ["ES256", "Ed25519"]);
const B = group("B", ["ES256", "ML-DSA-65"]).map((x) => ({ ...x, expect_verify_v1_without_mldsa65: { ok: false, error_contains: "ML-DSA-65 listed but not verifiable by this verifier" } }));
for (const c of [...A, ...B]) {
  const r = verifyV1(c.artefact);
  const want = c.expect;
  if (r.ok !== want.ok || (want.error_contains && !r.errors.some((e) => e.includes(want.error_contains)))) throw new Error(`${c.id}: got ${JSON.stringify(r.errors)}`);
}
// B without ML-DSA-65 support must fail closed. Two B cases fail before ML-DSA is reached (their
// ML-DSA-65 entry is the one stripped, or is unlisted) — record what such a verifier actually says.
for (const c of B) {
  const r = verifyV1(c.artefact, { can: ["ES256", "Ed25519", "Falcon-1024"] });
  if (r.ok) throw new Error(`${c.id}: passed without an ML-DSA-65 verifier`);
  if (!r.errors.some((e) => e.includes(c.expect_verify_v1_without_mldsa65.error_contains))) c.expect_verify_v1_without_mldsa65 = { ok: false, error_contains: c.expect.error_contains };
}

const out = {
  schema_version: "1.0",
  artefact_id: "pqam-cross-v1",
  about: "Cross-implementor cases for the AP2 PQC v1 signed input (algovoi-side/README.md 'v1 signed input'), generated by an independent JavaScript implementation (pqam interop/ap2-pq-conformance/ap2pqc-v1.mjs). Every case was checked by that implementation before writing. Test keys only.",
  generated_by: "https://github.com/eltociear/pqam/tree/main/interop/ap2-pq-conformance",
  signing_construction: "signed_input = 'AP2PQC/1.0/' + object_type + 0x00 + jcs(mandate_body) + 0x00 + jcs(signer_set)",
  mandate_body_source: `ap2-pqc-v1-algovoi-side.json mandate_body, unchanged (${UP.expected_jcs_bytes_length}-byte JCS, ${UP.expected_canonical_sha256})`,
  seed_material: { ...SEEDS, derivation: "ES256 / Ed25519: private_key = sha256(seed) (AlgoVoi's v1 derivation). ML-DSA-65: FIPS 204 keygen with xi = sha256(seed); pure, empty context, deterministic signing (rnd = 0)." },
  counts: { group_A: A.length, group_B: B.length },
  cases: [...A, ...B],
};
writeFileSync(new URL("pqam-cross-v1.json", import.meta.url), JSON.stringify(out, null, 1) + "\n");
console.log(`pqam-cross-v1.json: ${A.length} + ${B.length} cases, all checked`);
